class Solution {
    public int minPathSum(int[][] grid) {
        return f(grid, 0, 0);
    }

    private int f(int[][] g, int i, int j) {
        int m = g.length;
        int n = g[0].length;
        if (i == m - 1 && j == n - 1) return g[i][j];
        if (i == m - 1) return g[i][j] + f(g, i, j + 1);
        if (j == n - 1) return g[i][j] + f(g, i + 1, j);
        return g[i][j] + Math.min(f(g, i + 1, j), f(g, i, j + 1));
    }
}

class Solution {
    public int minPathSum(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;

        for (int j = 1; j < n; j++) grid[0][j] += grid[0][j - 1];
        for (int i = 1; i < m; i++) grid[i][0] += grid[i - 1][0];

        for (int i = 1; i < m; i++) {
            for (int j = 1; j < n; j++) {
                grid[i][j] += Math.min(grid[i - 1][j], grid[i][j - 1]);
            }
        }
        return grid[m - 1][n - 1];
    }
}

class Solution {
    public int minPathSum(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        int[] dp = new int[n];

        dp[0] = grid[0][0];
        for (int j = 1; j < n; j++) dp[j] = dp[j - 1] + grid[0][j];

        for (int i = 1; i < m; i++) {
            dp[0] += grid[i][0];
            for (int j = 1; j < n; j++) {
                dp[j] = grid[i][j] + Math.min(dp[j], dp[j - 1]);
            }
        }
        return dp[n - 1];
    }
}
